class Solution {
    public int countTriplets(int[] nums) {
        int[] cnt = new int[1 << 16];
        for (int a : nums)
            for (int b : nums)
                cnt[a & b]++;
        int res = 0;
        for (int c : nums)
            for (int v = 0; v < (1 << 16); v++)
                if ((v & c) == 0) res += cnt[v];
        return res;
    }
}
